import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Re-settles a SETTLED claim: its due is fixed again at the figure it would have today as an OPEN
 * claim bound by no statement: its live figure (today's rates, grades and floor) with the late
 * charge it would have gained by the sheet's today. Only a steward may re-settle a claim.
 */
public class ResettleClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request,
            Out<Resettlement> resettlement) throws InvalidClaimStatusException, ResettleException {
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new InvalidClaimStatusException("Only a SETTLED claim can be re-settled: this one is " + claim.getStatus());
        }
        String user = Audit.user(request);
        if (!Role.STEWARD.equals(roles.roleOf(sheet.id(), user))) {
            throw new ResettleException("Only a steward may re-settle a claim: " + user + " is a clerk");
        }
        Person person = people.find(sheet.id(), claim.getPersonId());
        Settings settings = settingsStore.find(sheet.id());
        BigDecimal figure = ClaimFigure.live(claim, rates.findAll(sheet.id()), person.gradeOn(claim.getDate()),
                settings, sheet.today());
        BigDecimal due = figure == null ? null
                : figure.add(ClaimFigure.lateAsOpen(claim, figure, settings, sheet.today()));
        BigDecimal old = claim.getSettledDue();
        claim.setSettledDue(due);
        resettlement.set(new Resettlement(old, due));
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigure;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the person's statement: their due-total now (the figures of their claims that count, added
 * up, skipping n/a; n/a when their grade in force today has no rate today and no claim that counts keeps a fixed
 * figure, has one under another grade in force on its date, or has one dated on or before today (under a
 * rate that has since ended); held to the sheet's cap; each claim at its date's grade's rate; an overdue claim's late charge on top), as the screen shows it. Every claim of theirs that counts is bound to its figure now (a live
 * one at least the sheet's floor), never its late charge;
 * every other claim of theirs is left unbound (live). The person's statement count goes up by one,
 * and the due-total and the sheet's today are kept as the last statement's.
 */
public class TakeStatement {
    public void take(@Val Sheet sheet, @Val Person person, ClaimRepository claims, RateRepository rates,
            SettingsRepository settings, PersonRepository people, Out<Statement> statementOut) {
        List<Rate> all = rates.findAll(sheet.id());
        Settings sheetSettings = settings.find(sheet.id());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        int counted = 0;
        for (Claim claim : claims.findByPerson(sheet.id(), person.getId())) {
            boolean counts = claim.counts(person.heldOn(claim.getDate()), sheet.today());
            if (counts) {
                counted++;
                if (claim.getSettledDue() != null || claim.boundDue() != null) fixed = true;
                String grade = person.gradeOn(claim.getDate());
                BigDecimal figure = ClaimFigure.of(claim, all, grade, sheetSettings, sheet.today());
                // A figure found under a grade other than today's is kept, whatever today's rate.
                if (figure != null && !grade.equals(person.gradeOn(sheet.today()))) fixed = true;
                // So is one dated on or before today, found under a rate that has since ended.
                if (figure != null && !claim.getDate().isAfter(sheet.today())) fixed = true;
                // The due-total carries the late charge; the claim is bound to the figure under it.
                if (figure != null) total = total.add(figure).add(ClaimFigure.late(claim, figure, sheetSettings, sheet.today()));
                claim.bind(true, figure);
            } else {
                claim.bind(false, null);
            }
            claims.save(claim);
        }
        String dueTotal = Rate.inForce(all, person.gradeOn(sheet.today()), sheet.today()).isEmpty() && !fixed
                ? "n/a" : sheetSettings.capped(total, sheet.today()).toPlainString();
        person.setStatements(person.getStatementCount() + 1, dueTotal, sheet.today());
        people.saveStatements(person);
        statementOut.set(new Statement(dueTotal, counted));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Settles the claim and fixes its due: its amount times the rate of its person's grade in force on its date, in force on the
 * claim's date, divided by 100 and rounded to two decimals as the claim rounds (by the sheet's policy date), at least the sheet's floor. With no such rate the due is
 * not fixed. A claim a statement bound is settled at its bound figure. The late charge it has gained
 * by the sheet's today is frozen in on top. The user who opened the claim may not settle it.
 * When a clerk (any user not made a steward) settles a claim whose due is above the sheet's clerk
 * limit, it goes to PENDING instead, its due left live until a steward approves or rejects it; a
 * due of n/a is within any limit. Before the clerk limit is considered, a claim whose due is above
 * the proof threshold in force on its date is refused while it has no proofs. Only a role the
 * permission matrix allows may settle.
 */
public class SettleClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request)
            throws InvalidClaimStatusException, SelfSettleException {
        settle(sheet, claim, Audit.user(request), people, rates, roles, settingsStore);
    }

    /** Settles the claim as the given user would, by the rules above; throws when it may not. */
    static void settle(Sheet sheet, Claim claim, String user, PersonRepository people, RateRepository rates,
            RoleRepository roles, SettingsRepository settingsStore)
            throws InvalidClaimStatusException, SelfSettleException {
        Person person = people.find(sheet.id(), claim.getPersonId());
        Settings settings = settingsStore.find(sheet.id());
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.allows("settle", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not settle a claim");
        }
        BigDecimal figure = claim.isStated() ? claim.getStatedDue()
                : ClaimFigure.live(claim, rates.findAll(sheet.id()), person.gradeOn(claim.getDate()), settings,
                        sheet.today());
        // The late charge is read while the claim is still OPEN.
        BigDecimal late = ClaimFigure.late(claim, figure, settings, sheet.today());
        if (claim.isDeferredOn(sheet.today())) {
            throw new InvalidClaimStatusException("A claim deferred until " + claim.getDeferredUntil() + " cannot be settled");
        }
        if (!claim.getStatus().canMoveTo(ClaimStatus.SETTLED)) {
            throw new InvalidClaimStatusException(claim.getStatus(), ClaimStatus.SETTLED);
        }
        if (user.equals(claim.getOpenedBy())) throw new SelfSettleException(user);
        BigDecimal due = figure == null ? null : figure.add(late);
        if (settings.needsProof(due, claim.getDate(), claim.getProofs())) throw new InvalidClaimStatusException(ProofRequired.MESSAGE);
        if (!settings.withinClerkLimit(due, sheet.today()) && Role.CLERK.equals(role)) {
            claim.moveTo(ClaimStatus.PENDING);
            return;
        }
        claim.moveTo(ClaimStatus.SETTLED);
        claim.setSettledDue(due);
    }
}

